package it.logisticasanchez.web.platform.security;

import jakarta.servlet.http.HttpServletRequest;
import java.security.SecureRandom;
import java.util.Base64;

/**
 * The per-request CSP nonce of the private areas (ADR 0018): generated by the header filter,
 * exposed to templates as the model attribute {@code cspNonce} for the few inline scripts the
 * layout needs ({@code <script th:attr="nonce=${cspNonce}">}).
 */
public final class CspNonce {

    public static final String ATTRIBUTE = CspNonce.class.getName();
    private static final SecureRandom RANDOM = new SecureRandom();

    private CspNonce() {}

    static String generate() {
        byte[] bytes = new byte[16];
        RANDOM.nextBytes(bytes);
        return Base64.getEncoder().encodeToString(bytes);
    }

    /** The nonce of this request, or null on a public route. */
    public static String of(HttpServletRequest request) {
        Object value = request.getAttribute(ATTRIBUTE);
        return value instanceof String s ? s : null;
    }
}
